  \node (m) at (0,0) {$J\in[M]$};
  \node[draw] (enc) at (2,0) {$e:[M]\to\mathcal X^n$};
  \node (x) at (4.5,0) {$X^n=e(J)$};
  \node[draw] (ch) at (6.7,0) {$W^n$};
  \node (y) at (9,0) {$Y^n$};
